import { Button } from "~/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "~/components/ui/dialog";
import { useState } from "react";
import { TextError } from "~/components/TextError";
import { Spinner } from "~/components/Spinner";
import { useDelete } from "./use-delete";

export function DeleteBtn({
  recordId,
}: {
  recordId: string;
}) {
  const [open, setOpen] = useState(false);
  const { error, loading, handleDelete } = useDelete({
    id: recordId,
    onClose: () => setOpen(false),
  });
  return (
    <Dialog open={open} onOpenChange={(open) => setOpen(open)}>
      <Button asChild variant="destructive">
        <DialogTrigger>Hapus</DialogTrigger>
      </Button>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="text-big">Hapus catatan riwayat?</DialogTitle>
          <div className="flex justify-between mt-5">
            <Button asChild>
              <DialogClose>Batal</DialogClose>
            </Button>
            <Button onClick={handleDelete} variant="destructive">
              Hapus <Spinner when={loading} />
            </Button>
          </div>
          <TextError>{error}</TextError>
        </DialogHeader>
        <DialogDescription>Catatan riwayat ini beserta barisnya dihapus permanen.</DialogDescription>
      </DialogContent>
    </Dialog>
  );
}
